import threading
import os
import time
import queue
from pathlib import Path
from typing import List, Dict, Optional
import random

class FileLockManager:
    def __init__(self):
        self._locks: Dict[str, threading.Lock] = {}
        self._global_lock = threading.Lock()

    def get_lock(self, filepath: str) -> threading.Lock:
        with self._global_lock:
            if filepath not in self._locks:
                self._locks[filepath] = threading.Lock()
            return self._locks[filepath]

def process_file(filepath: str, lock_manager: FileLockManager, processing_time: Optional[float] = None) -> Dict:
    lock = lock_manager.get_lock(filepath)

    with lock:
        if processing_time is None:
            processing_time = random.uniform(0.1, 0.3)

        time.sleep(processing_time)

        result = {
            'filepath': filepath,
            'thread_name': threading.current_thread().name,
            'start_time': time.time(),
            'duration': processing_time,
            'status': 'success'
        }

        try:
            with open(filepath, 'r+') as f:
                content = f.read()
                new_content = f"[Processed by {threading.current_thread().name}]\n{content}"
                f.seek(0)
                f.write(new_content)
                f.truncate()
        except Exception as e:
            result['status'] = 'error'
            result['error'] = str(e)

        result['end_time'] = time.time()
        return result

def worker_thread(lock_manager: FileLockManager, file_queue: queue.Queue,
                  results: List[Dict], results_lock: threading.Lock) -> None:
    while True:
        try:
            filepath = file_queue.get(timeout=0.5)
        except queue.Empty:
            break

        try:
            result = process_file(filepath, lock_manager)
            with results_lock:
                results.append(result)
        except Exception as e:
            with results_lock:
                results.append({
                    'filepath': filepath,
                    'thread_name': threading.current_thread().name,
                    'status': 'error',
                    'error': str(e)
                })
        finally:
            file_queue.task_done()

